INSERT INTO `prodotti` (`id`, `idFornitore`, `idCategoria`, `nome`, `prezzo`, `descrizione`, `modello`) VALUES
(1, 1, 1, 'MotoTofu', 999.67, 'La motocicletta pi? eco-sostenibile del mercato, interamente composta da materiali vegetali :D', '/MotosBurro/json/moto5.json'),
(2, 7, 1, 'MotoLegumi', 199.67, 'La prima motocicletta auto-alimentata, sar? infatti necessario mangiare componenti non fondamentali al funzionamento meccanico di quest\'ultima (ad esempio le estremit? del manubrio\'), eco-sostenibile, autonomia variabile a seconda dell\'efficienza dell\'apparato digestivo del pilota, mono-uso', '/MotosBurro/json/moto4.json'),
(3, 3, 4, 'MotoFormaggino', 1499.67, 'Formaggino spalmabile stagionato, massime prestazioni da pista grazie alle untissime ruote, e massima sicurezza su strada -gli automobilisti percepiranno il vostro inconfondibile odore e saranno all\'erta per il vostro arrivo-', '/MotosBurro/json/moto2.json'),
(4, 3, 3, 'CascoFormaggino', 59.67, 'Il casco, grazie ai suoi strati di eterogenee stagionature, offre morbido confort all\'interno, combinato ad una dura protezione esterna', '/MotosBurro/json/casco1.json'),
(5, 6, 4, 'MotoBurroVeloce', 6769.00, 'Moto velocissima, fatta con burro di miglire qualità che garantisce uno scorrimento ottimale permettendo di raggiungere velocità impressionanti', '/MotosBurro/json/moto3.json'),
(6, 4, 6, 'MotoStagionata', 969.00, 'Moto di stagionatura secolare che garantisce toni speziati ed emozioni pure', '/MotosBurro/json/moto1.json'),
(8, 9, 5, 'MonocicloMultiformaggio', 720.00, 'Un monociclo creato dai migliori ingeneri con le più sofisticate leghe di formaggio', '/MotosBurro/json/monociclo1.json'),
(9, 6, 2, 'MotoMotoreMonocilindrico', 186.00, 'Un motore monocilindrico 2 tempi in burro raffreddato a liquido', '/MotosBurro/json/motore1.json'),
(10, 6, 2, 'MotoMotoreBicilindrico', 365.00, 'Un motore bicilindrico 2 tempi in formaggio forgiato studiato per garantire la massima potenza', '/MotosBurro/json/motore2.json'),
(11, 4, 2, 'SospensioniBurrose', 67.00, 'Sospensioni in burro, create per garantire la migliore scorrevolezza su qualsiasi terreno', '/MotosBurro/json/sospensioni2.json'),
(12, 1, 1, 'MotOlio', 30.00, 'Un olio creato da un mix di semi scelto, garantisce la massima scorrevolezza enche sui motori vegani più fibrosi', '/MotosBurro/json/olio1.json'),
(13, 9, 6, 'Carroformaggiato', 1945.00, 'Non è una moto, ma fa il suo lavoro, armato di cannoni spara crosta da 45mm e dotato di una corazza in formaggio balistico da 60mm, potrai affrontare qualunque intollerante al lattosio', '/MotosBurro/json/carroarmato1.json'),
(14, 7, 3, 'CascoScodella', 46.00, 'Un casco multifunzione, oltre che fungere da casco è anche utilizzabile come scodella per il proprio formaggio', '/MotosBurro/json/casco2.json'),
(15, 3, 3, 'CascoProteico', 71.00, 'Grazie all\'elevato tenore di proteine garantisce un\'ottima resistenza strutturale quindi un\'eccellente protezione dagli impatti, purè con i formaggi più stagionati', '/MotosBurro/json/casco3.json');

